#include "launch_options.h"
#include <cstring>
namespace billiardgl {
LaunchOptions parseLaunchOptions(int argc,char* argv[]){LaunchOptions r;bool automation=false,headless=false,rendered=false;for(int i=1;i<argc;++i){if(!std::strcmp(argv[i],"--automation"))automation=true;else if(!std::strcmp(argv[i],"--headless"))headless=true;else if(!std::strcmp(argv[i],"--rendered"))rendered=true;else if(!std::strcmp(argv[i],"--transport")&&i+1<argc)r.transport=argv[++i];else if(!std::strcmp(argv[i],"--windowed"))r.runtime.windowedMode=true;else if(!std::strcmp(argv[i],"--fullscreen"))r.runtime.windowedMode=false;else if(!std::strcmp(argv[i],"--screenshot")&&i+1<argc){r.runtime.screenshotPath=argv[++i];r.runtime.windowedMode=true;}else if(!std::strcmp(argv[i],"--screenshot-scene")&&i+1<argc){const char*s=argv[++i];if(!std::strcmp(s,"default"))r.runtime.screenshotScene=ScreenshotScene::Default;else if(!std::strcmp(s,"help"))r.runtime.screenshotScene=ScreenshotScene::Help;else if(!std::strcmp(s,"aim"))r.runtime.screenshotScene=ScreenshotScene::Aim;else if(!std::strcmp(s,"after-shot"))r.runtime.screenshotScene=ScreenshotScene::AfterShot;else{r.ok=false;r.error="unknown screenshot scene";}}else{r.ok=false;r.error=std::string("unknown option: ")+argv[i];}}if((headless||rendered)&&!automation){r.ok=false;r.error="mode requires automation";}if(automation&&headless==rendered){r.ok=false;r.error="choose exactly one automation mode";}if(automation&&r.transport!="stdio"){r.ok=false;r.error="unsupported transport";}if(automation)r.mode=headless?RunMode::AutomationHeadless:RunMode::AutomationRendered;return r;}
}
